CREATE TABLE "User" ("id" TEXT NOT NULL, "email" TEXT NOT NULL, "name" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Player" ("id" TEXT NOT NULL, "espnId" TEXT, "name" TEXT NOT NULL, "team" TEXT, "position" TEXT NOT NULL, "active" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Player_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Roster" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "name" TEXT NOT NULL, "scoringFormat" TEXT NOT NULL DEFAULT 'PPR', "flexSpots" INTEGER NOT NULL DEFAULT 1, "benchSize" INTEGER NOT NULL DEFAULT 6, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Roster_pkey" PRIMARY KEY ("id"));
CREATE TABLE "RosterPlayer" ("id" TEXT NOT NULL, "rosterId" TEXT NOT NULL, "playerId" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'BENCH', CONSTRAINT "RosterPlayer_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Stadium" ("id" TEXT NOT NULL, "espnVenueId" TEXT, "name" TEXT NOT NULL, "city" TEXT, "state" TEXT, "latitude" DOUBLE PRECISION, "longitude" DOUBLE PRECISION, "isDome" BOOLEAN NOT NULL DEFAULT false, "surface" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Stadium_pkey" PRIMARY KEY ("id"));
CREATE TABLE "WeeklyProjection" ("id" TEXT NOT NULL, "playerId" TEXT NOT NULL, "season" INTEGER NOT NULL, "week" INTEGER NOT NULL, "source" TEXT NOT NULL, "points" DOUBLE PRECISION NOT NULL, "rawPayload" JSONB, "retrievedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "WeeklyProjection_pkey" PRIMARY KEY ("id"));
CREATE TABLE "PlayerUsage" ("id" TEXT NOT NULL, "playerId" TEXT NOT NULL, "season" INTEGER NOT NULL, "week" INTEGER NOT NULL, "snapShare" DOUBLE PRECISION, "touches" INTEGER, "targets" INTEGER, "adjustment" DOUBLE PRECISION NOT NULL DEFAULT 0, CONSTRAINT "PlayerUsage_pkey" PRIMARY KEY ("id"));
CREATE TABLE "HistoricalPerformance" ("id" TEXT NOT NULL, "playerId" TEXT NOT NULL, "opponent" TEXT NOT NULL, "pointsPerGame" DOUBLE PRECISION NOT NULL, "adjustment" DOUBLE PRECISION NOT NULL DEFAULT 0, CONSTRAINT "HistoricalPerformance_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Matchup" ("id" TEXT NOT NULL, "season" INTEGER NOT NULL, "week" INTEGER NOT NULL, "team" TEXT NOT NULL, "opponent" TEXT NOT NULL, "position" TEXT NOT NULL, "stadiumId" TEXT, "defenseRank" INTEGER, "pointsAllowed" DOUBLE PRECISION, "adjustment" DOUBLE PRECISION NOT NULL DEFAULT 0, "rawPayload" JSONB, "retrievedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Matchup_pkey" PRIMARY KEY ("id"));
CREATE TABLE "WeatherForecast" ("id" TEXT NOT NULL, "stadiumId" TEXT NOT NULL, "season" INTEGER NOT NULL, "week" INTEGER NOT NULL, "conditions" TEXT, "temperatureF" DOUBLE PRECISION, "windMph" DOUBLE PRECISION, "precipitation" DOUBLE PRECISION, "adjustment" DOUBLE PRECISION NOT NULL DEFAULT 0, "forecastAt" TIMESTAMP(3) NOT NULL, "retrievedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "WeatherForecast_pkey" PRIMARY KEY ("id"));
CREATE TABLE "DataRefresh" ("id" TEXT NOT NULL, "provider" TEXT NOT NULL, "resource" TEXT NOT NULL, "status" TEXT NOT NULL, "startedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "completedAt" TIMESTAMP(3), "detail" JSONB, CONSTRAINT "DataRefresh_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "User_email_key" ON "User"("email");
CREATE UNIQUE INDEX "Player_espnId_key" ON "Player"("espnId");
CREATE INDEX "Player_team_position_idx" ON "Player"("team", "position");
CREATE INDEX "Roster_userId_idx" ON "Roster"("userId");
CREATE INDEX "RosterPlayer_playerId_idx" ON "RosterPlayer"("playerId");
CREATE UNIQUE INDEX "RosterPlayer_rosterId_playerId_key" ON "RosterPlayer"("rosterId", "playerId");
CREATE UNIQUE INDEX "Stadium_espnVenueId_key" ON "Stadium"("espnVenueId");
CREATE INDEX "WeeklyProjection_season_week_idx" ON "WeeklyProjection"("season", "week");
CREATE UNIQUE INDEX "WeeklyProjection_playerId_season_week_source_key" ON "WeeklyProjection"("playerId", "season", "week", "source");
CREATE INDEX "PlayerUsage_season_week_idx" ON "PlayerUsage"("season", "week");
CREATE UNIQUE INDEX "PlayerUsage_playerId_season_week_key" ON "PlayerUsage"("playerId", "season", "week");
CREATE UNIQUE INDEX "HistoricalPerformance_playerId_opponent_key" ON "HistoricalPerformance"("playerId", "opponent");
CREATE INDEX "Matchup_season_week_opponent_idx" ON "Matchup"("season", "week", "opponent");
CREATE UNIQUE INDEX "Matchup_season_week_team_position_key" ON "Matchup"("season", "week", "team", "position");
CREATE INDEX "WeatherForecast_season_week_idx" ON "WeatherForecast"("season", "week");
CREATE UNIQUE INDEX "WeatherForecast_stadiumId_season_week_key" ON "WeatherForecast"("stadiumId", "season", "week");
CREATE INDEX "DataRefresh_provider_resource_startedAt_idx" ON "DataRefresh"("provider", "resource", "startedAt");
ALTER TABLE "Roster" ADD CONSTRAINT "Roster_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "RosterPlayer" ADD CONSTRAINT "RosterPlayer_rosterId_fkey" FOREIGN KEY ("rosterId") REFERENCES "Roster"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "RosterPlayer" ADD CONSTRAINT "RosterPlayer_playerId_fkey" FOREIGN KEY ("playerId") REFERENCES "Player"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "WeeklyProjection" ADD CONSTRAINT "WeeklyProjection_playerId_fkey" FOREIGN KEY ("playerId") REFERENCES "Player"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "PlayerUsage" ADD CONSTRAINT "PlayerUsage_playerId_fkey" FOREIGN KEY ("playerId") REFERENCES "Player"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "HistoricalPerformance" ADD CONSTRAINT "HistoricalPerformance_playerId_fkey" FOREIGN KEY ("playerId") REFERENCES "Player"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Matchup" ADD CONSTRAINT "Matchup_stadiumId_fkey" FOREIGN KEY ("stadiumId") REFERENCES "Stadium"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "WeatherForecast" ADD CONSTRAINT "WeatherForecast_stadiumId_fkey" FOREIGN KEY ("stadiumId") REFERENCES "Stadium"("id") ON DELETE CASCADE ON UPDATE CASCADE;
